class TestMakeIsolateSuffix:
    def test_neither_input_yields_empty(self, sm):
        assert sm.make_isolate_suffix() == ""

    def test_version_only(self, sm):
        assert sm.make_isolate_suffix(isolate_version=2) == "v2"

    def test_lab_passage_only(self, sm):
        assert sm.make_isolate_suffix(lab_passage=True) == "L"

    def test_version_and_lab_passage(self, sm):
        assert sm.make_isolate_suffix(isolate_version=2, lab_passage=True) == "v2.L"

